'use strict';
(()=>{const panels={portal:'portalPanel',home:'homePanel',form:'capture',saved:'review',status:'tracker',admin:'adminPanel',profile:'profilePanel',settings:'settingsPanel',import:'importPanel',changelog:'changelogPanel'},buttons={portal:'portalHomeTab',form:'liveTab',saved:'savedTab',status:'statusTab',admin:'adminTab',profile:'profileTab',settings:'settingsTab',import:'importTab',changelog:'changelogTab',home:'homeTab'};let api,armed=false,restoring=false;const $=id=>document.getElementById(id),key=()=> 'guhuza.navigation.v1.'+api.user().id;function read(){try{return JSON.parse(sessionStorage.getItem(key())||'null');}catch{return null;}}
const teamIds=['hr','testing','data','marketing','sales'];let lastHash='',locationQueue=Promise.resolve();
function toHash(state){const q=new URLSearchParams(),add=(key,value)=>{if(value!==undefined&&value!==null&&value!=='')q.set(key,String(value));};let path='/home';if(state.page==='portal'){const r=state.portal||{};if(r.view==='settings'){path='/admin/people';add('team',r.peopleGroup);add('person',r.person);}else if(teamIds.includes(r.team)){path='/'+r.team;const area={training:'training',projects:'tasks',meetings:'meetings',links:'spreadsheets',teamadmin:'admin'}[r.view];if(area)path+='/'+area;if(r.view==='training'){add('tab',r.learningTab);add('lesson',r.learningItem);add('path',r.learningPath);add('section',r.learningSection);}if(r.view==='projects'){add('view',r.workTab);add('scope',r.workScope);add('month',r.workMonth);add('day',r.workDay);add('work',r.work);}if(r.view==='meetings')add('date',r.meetingDay);}}else if(['profile','settings','changelog'].includes(state.page))path='/'+state.page;else{path='/hr/interviews'+({home:'',form:'/new',saved:'/mine',status:'/follow-up',admin:'/admin',import:'/import'}[state.page]||'');if(state.page==='saved'){add('id',state.interview?.browse?null:state.interview?.id);add('scope',state.interview?.scope);add('job',state.library?.job);}if(state.page==='admin'){add('section',state.admin?.section);add('mode',state.admin?.mode);add('group',state.admin?.group);}}return '#'+path+(q.size?'?'+q.toString():'');}
function fromHash(hash){if(!hash?.startsWith('#/'))return null;try{const [raw,query='']=hash.slice(1).split('?'),parts=raw.split('/').filter(Boolean),q=new URLSearchParams(query),state={page:'portal',portalVersion:3,portal:{view:'home'}},get=key=>q.get(key)?.slice(0,250);if(parts[0]==='admin'&&parts[1]==='people'){state.portal={view:'settings',peopleGroup:get('team'),person:get('person')};return state;}if(['profile','settings','changelog'].includes(parts[0])){state.page=parts[0];delete state.portal;return state;}if(!teamIds.includes(parts[0]))return state;const team=parts[0];if(team==='hr'&&parts[1]==='interviews'){state.page=({new:'form',mine:'saved','follow-up':'status',admin:'admin',import:'import'})[parts[2]]||'home';delete state.portal;if(state.page==='saved'){state.interview={id:get('id'),scope:get('scope')==='team'?'team':'own',browse:!get('id')};state.library={mode:get('job')?'jobs':'recent',job:get('job')};}if(state.page==='admin')state.admin={section:get('section'),mode:get('mode'),group:get('group')};return state;}const view=({training:'training',tasks:'projects',meetings:'meetings',spreadsheets:'links',admin:'teamadmin'})[parts[1]]||'team';state.portal={view,team};if(view==='training')Object.assign(state.portal,{learningTab:get('tab'),learningItem:get('lesson'),learningPath:get('path'),learningSection:get('section')});if(view==='projects')Object.assign(state.portal,{workTab:get('view'),workScope:get('scope'),workMonth:get('month'),workDay:get('day'),work:get('work')});if(view==='meetings')state.portal.meetingDay=get('date');return state;}catch{return null;}}
function saveAddress(state){if(!window.location||!window.history||window.GuhuzaActAs?.isChild)return;const hash=toHash(state);if(window.location.hash!==hash)window.history.pushState(null,'',hash);lastHash=hash;}
function locationChanged(){if(!armed||!api?.user()||!window.location?.hash?.startsWith('#/')||window.location.hash===lastHash)return;const hash=window.location.hash;lastHash=hash;const state=fromHash(hash);locationQueue=locationQueue.then(()=>restore(state));}

function save(){if(!armed||restoring||!api?.user()||window.GuhuzaActAs?.isChild||$('workspace').hidden)return;const page=Object.keys(panels).find(p=>$(panels[p])&&!$(panels[p]).hidden);if(!page)return;const state={page,portalVersion:3};if(page==='portal')state.portal=GuhuzaTeams.navigationState();if(page==='saved'){state.interview=legacy.navigationState();state.library=GuhuzaLibrary.navigationState();}if(page==='status')state.library=GuhuzaLibrary.navigationState();if(page==='admin'){state.admin=GuhuzaAdmin.navigationState();}try{sessionStorage.setItem(key(),JSON.stringify(state));}catch{}saveAddress(state);}
async function restore(forced){armed=false;restoring=true;const state=forced||fromHash(window.location?.hash)||read();try{if(!state?.portalVersion){GuhuzaTeams.home();return;}if(state.page==='portal'){await GuhuzaTeams.restoreNavigation(state.portal);return;}if(!state||!Object.hasOwn(panels,state.page)||window.GuhuzaActAs?.isChild){GuhuzaTeams.home();return;}if(state.page==='admin'){if(!api.profile()?.is_admin){GuhuzaUI.show('home');return;}await GuhuzaAdmin.restoreNavigation(state.admin||{});return;}if(state.page==='saved'&&state.interview?.id&&!state.interview.browse){const record=legacy.records().find(r=>r.id===state.interview.id),owns=record&&window.GuhuzaRecordAccess.owns(record.id),team=state.interview.scope==='team'&&window.GuhuzaRecordAccess.canViewAll();if(record&&(owns||team)){if(team)legacy.openTeam(record.id);else legacy.open(record.id);return;}}$(buttons[state.page])?.click();if(state.page==='saved'||state.page==='status')GuhuzaLibrary.restoreNavigation(state.library||{});if(state.page==='changelog')GuhuzaChanges.render();}catch{GuhuzaTeams.home();}finally{restoring=false;armed=true;save();}}
window.GuhuzaNavigation={start(context){api=context;for(const event of ['click','input','change'])document.addEventListener(event,()=>queueMicrotask(save));window.addEventListener('popstate',locationChanged);window.addEventListener('hashchange',locationChanged);window.addEventListener('pagehide',save);window.addEventListener('beforeunload',save);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')save();});},restore,save,toHash,fromHash,stop(){armed=false;}};
})();
